CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, community_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('traveller','demo_admin')), synthetic INTEGER NOT NULL, gender TEXT NOT NULL, adult INTEGER NOT NULL, sharing INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS trips (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL, community_id TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS trip_candidates ON trips(community_id,status);
CREATE TABLE IF NOT EXISTS groups (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,trip_id TEXT NOT NULL REFERENCES trips(id),accepted_version INTEGER NOT NULL DEFAULT 0,fare_accepted_version INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,paid INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(group_id,user_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_membership ON members(user_id) WHERE active=1;
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,href TEXT NOT NULL,created INTEGER NOT NULL,read INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS blocks (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,target_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(user_id,target_id));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,target_id TEXT,body TEXT NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL,community_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY,group_id TEXT REFERENCES groups(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,kind TEXT NOT NULL,body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS hubs (id TEXT PRIMARY KEY,name TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS route_edges (id TEXT PRIMARY KEY,origin TEXT NOT NULL REFERENCES hubs(id),destination TEXT NOT NULL REFERENCES hubs(id),meters INTEGER NOT NULL,minutes INTEGER NOT NULL);
INSERT OR IGNORE INTO migrations(version,applied_at) VALUES(1,unixepoch()*1000);
